      && verifier.VerifyString(tablePos, 30 /*FIRST_OBSERVED*/, false)
      && verifier.VerifyString(tablePos, 32 /*LAST_OBSERVED*/, false)
      && verifier.VerifyString(tablePos, 34 /*OPERATOR*/, false)
      && verifier.VerifyField(tablePos, 36 /*FREQUENCY_MHZ*/, 8 /*double*/, 8, false)
      && verifier.VerifyString(tablePos, 38 /*SITE_NAME*/, false)
      && verifier.VerifyString(tablePos, 40 /*COUNTRY_CODE*/, false)
      && verifier.VerifyVectorOfTables(tablePos, 42 /*SOURCES*/, TBSProvenanceVerify.Verify, true)
      && verifier.VerifyTable(tablePos, 44 /*CONSENSUS*/, TBSConsensusVerify.Verify, true)
      && verifier.VerifyTableEnd(tablePos);
  }
}
